const axios = require("axios");

const LLM_ENDPOINT = "https://openrouter.ai/api/v1/chat/completions";
const MODEL = "deepseek/deepseek-chat-v3-0324:free";

// ✅ Вызов LLM
async function callLLM(apiKey, model, prompt) {
  console.log(`🚀 Вызов LLM: модель=${model}`);
  console.log(`📝 Длина промпта: ${prompt?.length || 0} символов`);

  if (!apiKey || apiKey.trim() === "") {
    console.error("❌ Ошибка: API ключ отсутствует или пустой");
    return { success: false, error: "API ключ отсутствует", content: null };
  }

  if (!model || model.trim() === "") {
    console.error("❌ Ошибка: модель не указана");
    return { success: false, error: "Модель не указана", content: null };
  }

  try {
    const res = await axios.post(
      LLM_ENDPOINT,
      {
        model: model,
        messages: [{ role: "user", content: prompt }],
        temperature: 0.7,
        max_tokens: 8000,
      },
      {
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        timeout: 60000,
      },
    );

    if (!res.data) {
      console.error("❌ Ошибка: пустой ответ от API");
      return { success: false, error: "Пустой ответ от API", content: null };
    }

    if (!res.data.choices || !res.data.choices[0]) {
      console.error("❌ Ошибка: некорректная структура ответа", JSON.stringify(res.data));
      return { success: false, error: "Некорректная структура ответа", content: null };
    }

    const content = res.data.choices[0]?.message?.content?.trim();
    const finishReason = res.data.choices[0]?.finish_reason;

    console.log(`✅ Ответ от LLM получен (длина=${content?.length || 0}, finish_reason=${finishReason})`);

    if (!content) {
      console.error("❌ Ошибка: пустой контент в ответе");
      return { success: false, error: "Пустой контент в ответе", content: null };
    }

    return { success: true, content, finishReason };
  } catch (err) {
    let errorMessage = "";
    if (err.response) {
      errorMessage = `HTTP ${err.response.status}: ${JSON.stringify(err.response.data)}`;
      console.error("❌ Ошибка при вызове LLM (ответ сервера):", errorMessage);
    } else if (err.request) {
      errorMessage = "Нет ответа от сервера";
      console.error("❌ Ошибка при вызове LLM (нет ответа):", err.message);
    } else {
      errorMessage = err.message;
      console.error("❌ Ошибка при вызове LLM:", err.message);
    }
    return { success: false, error: errorMessage, content: null };
  }
}

// ✅ Чистим ```json ... ```
function cleanJsonString(str) {
  if (!str) return str;
  let cleaned = str
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();
  return cleaned;
}

// ✅ Функция для попытки восстановить обрезанный JSON
function tryToFixTruncatedJson(jsonStr) {
  if (!jsonStr) return jsonStr;

  let brackets = 0;
  let braces = 0;
  let inString = false;
  let escape = false;

  for (let i = 0; i < jsonStr.length; i++) {
    const char = jsonStr[i];

    if (escape) {
      escape = false;
      continue;
    }

    if (char === '\\') {
      escape = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
      continue;
    }

    if (!inString) {
      if (char === '[') brackets++;
      if (char === ']') brackets--;
      if (char === '{') braces++;
      if (char === '}') braces--;
    }
  }

  if (brackets > 0 || braces > 0) {
    console.log(`⚠️ Обнаружен обрезанный JSON: brackets=${brackets}, braces=${braces}`);

    let fixed = jsonStr;
    for (let i = 0; i < braces; i++) {
      fixed += '}';
    }
    for (let i = 0; i < brackets; i++) {
      fixed += ']';
    }

    console.log(`🔧 Добавлено ${braces} закрывающих фигурных скобок и ${brackets} квадратных скобок`);
    return fixed;
  }

  return jsonStr;
}

// ✅ Основная функция извлечения JSON
function extractJsonFromResponse(str) {
  if (!str) return null;

  // Ищем JSON-блок, ограниченный ```json ... ```
  const jsonRegex = /```json\s*([\s\S]*?)```/i;
  const match = str.match(jsonRegex);

  let extracted = null;

  if (match && match[1]) {
    console.log("🔍 Найден JSON блок в обратных кавычках");
    extracted = match[1].trim();
  } else {
    // Ищем JSON-блок, ограниченный только ```
    const codeRegex = /```\s*([\s\S]*?)```/i;
    const codeMatch = str.match(codeRegex);

    if (codeMatch && codeMatch[1]) {
      console.log("🔍 Найден блок кода без указания json");
      extracted = codeMatch[1].trim();
    } else {
      // Если нет обратных кавычек, ищем первый символ [ или {
      const firstBracket = str.indexOf('[');
      const firstBrace = str.indexOf('{');
      const startIndex = firstBracket !== -1 && (firstBracket < firstBrace || firstBrace === -1) 
        ? firstBracket 
        : firstBrace;

      if (startIndex === -1) {
        console.log("⚠️ JSON блок не найден");
        return cleanJsonString(str);
      }

      let brackets = 0;
      let braces = 0;
      let inString = false;
      let escape = false;
      let endIndex = -1;

      for (let i = startIndex; i < str.length; i++) {
        const char = str[i];

        if (escape) {
          escape = false;
          continue;
        }

        if (char === '\\') {
          escape = true;
          continue;
        }

        if (char === '"') {
          inString = !inString;
          continue;
        }

        if (!inString) {
          if (char === '[') brackets++;
          if (char === ']') brackets--;
          if (char === '{') braces++;
          if (char === '}') braces--;

          if (brackets === 0 && braces === 0 && (char === ']' || char === '}')) {
            endIndex = i + 1;
            break;
          }
        }
      }

      if (endIndex !== -1) {
        extracted = str.substring(startIndex, endIndex);
        console.log(`🔍 Найден JSON ${str[startIndex] === '[' ? 'массив' : 'объект'} длиной ${extracted.length} символов`);
      } else {
        extracted = str.substring(startIndex);
        console.log(`⚠️ JSON обрезан, берем от позиции ${startIndex}`);
      }
    }
  }

  if (extracted) {
    const fixed = tryToFixTruncatedJson(extracted);
    return fixed;
  }

  console.log("⚠️ JSON блок не найден, пробуем очистить всю строку");
  return cleanJsonString(str);
}

// ✅ Проверка структуры complect (адаптировано из вашего примера)
function isValidComplect(item, index) {
  if (!item || typeof item !== "object") {
    return { valid: false, reason: `Элемент ${index} не является объектом` };
  }

  // Проверяем наличие поля complect
  if (!("complect" in item)) {
    return { valid: false, reason: `Элемент ${index} не содержит поле "complect"` };
  }

  const complect = item.complect;

  // Проверяем, что complect - массив из 4 элементов
  if (!Array.isArray(complect)) {
    return { valid: false, reason: `Элемент ${index}: поле "complect" не является массивом` };
  }

  if (complect.length !== 4) {
    return { valid: false, reason: `Элемент ${index}: массив "complect" должен содержать 4 элемента, получено ${complect.length}` };
  }

  // Проверяем каждый элемент complect
  for (let i = 0; i < complect.length; i++) {
    const stage = complect[i];
    const expectedStage = `Этап ${i + 1}`;

    if (!stage || typeof stage !== "object") {
      return { valid: false, reason: `Элемент ${index}: complect[${i}] не является объектом` };
    }

    if (!("subject" in stage)) {
      return { valid: false, reason: `Элемент ${index}: complect[${i}] не содержит поле "subject"` };
    }

    if (!("body" in stage)) {
      return { valid: false, reason: `Элемент ${index}: complect[${i}] не содержит поле "body"` };
    }

    if (!("stage" in stage)) {
      return { valid: false, reason: `Элемент ${index}: complect[${i}] не содержит поле "stage"` };
    }

    if (stage.stage !== expectedStage) {
      return { valid: false, reason: `Элемент ${index}: complect[${i}].stage должно быть "${expectedStage}", получено "${stage.stage}"` };
    }

    if (typeof stage.subject !== "string" || stage.subject.trim() === "") {
      return { valid: false, reason: `Элемент ${index}: complect[${i}].subject пустое или не строка` };
    }

    if (typeof stage.body !== "string" || stage.body.trim() === "") {
      return { valid: false, reason: `Элемент ${index}: complect[${i}].body пустое или не строка` };
    }
  }

  return { valid: true };
}

// ✅ Главная функция
async function main(prompt, api_key, model) {
  const logs = [];
  const startTime = Date.now();

  logs.push(`🚀 Начало выполнения (${new Date().toISOString()})`);

  if (!prompt || prompt.trim() === "") {
    logs.push("❌ Ошибка: промпт отсутствует или пустой");
    return { items: [], logs: logs.join("\n") };
  }

  logs.push(`📝 Промпт: ${prompt.substring(0, 100)}${prompt.length > 100 ? "..." : ""}`);

  const modelToUse = model && model.trim() ? model : MODEL;
  logs.push(`🤖 Используемая модель: ${modelToUse}`);
  logs.push(`🔑 API ключ: ${api_key ? `${api_key.substring(0, 8)}...${api_key.substring(api_key.length - 4)}` : "отсутствует"}`);

  const result = await callLLM(api_key, modelToUse, prompt);

  if (!result.success) {
    logs.push(`❌ Ошибка вызова LLM: ${result.error}`);
    return { items: [], logs: logs.join("\n") };
  }

  logs.push(`✅ LLM ответил успешно, длина ответа: ${result.content.length} символов`);
  logs.push(`📄 Первые 200 символов ответа: ${result.content.substring(0, 200)}`);
  logs.push(`📄 Последние 200 символов ответа: ${result.content.substring(Math.max(0, result.content.length - 200))}`);

  if (!result.content) {
    logs.push("❌ Ошибка: пустой ответ от LLM");
    return { items: [], logs: logs.join("\n") };
  }

  try {
    logs.push("🔍 Начинаем парсинг JSON...");
    const cleaned = extractJsonFromResponse(result.content);
    logs.push(`🧹 Очищенная строка (первые 200 символов): ${cleaned.substring(0, 200)}`);
    logs.push(`🧹 Очищенная строка (последние 200 символов): ${cleaned.substring(Math.max(0, cleaned.length - 200))}`);

    let parsed;
    try {
      parsed = JSON.parse(cleaned);
      logs.push("✅ JSON успешно распарсен");
    } catch (parseError) {
      logs.push(`❌ Ошибка парсинга JSON: ${parseError.message}`);
      logs.push(`📄 Проблемная строка (первые 500 символов): ${cleaned.substring(0, 500)}`);
      logs.push(`📄 Проблемная строка (последние 500 символов): ${cleaned.substring(Math.max(0, cleaned.length - 500))}`);
      return { items: [], logs: logs.join("\n") };
    }

    let itemsToValidate = [];

    if (Array.isArray(parsed)) {
      logs.push(`📊 Получен массив из ${parsed.length} элементов`);
      itemsToValidate = parsed;
    } else if (parsed && typeof parsed === "object") {
      logs.push("📊 Получен объект, оборачиваем в массив");
      itemsToValidate = [parsed];
    } else {
      logs.push(`❌ Ошибка: результат не массив и не объект, тип: ${typeof parsed}`);
      return { items: [], logs: logs.join("\n") };
    }

    const validItems = [];
    const invalidItems = [];

    for (let i = 0; i < itemsToValidate.length; i++) {
      const validation = isValidComplect(itemsToValidate[i], i);
      if (validation.valid) {
        validItems.push(itemsToValidate[i]);
        logs.push(`✅ Элемент ${i} валиден: содержит complect с 4 этапами`);
      } else {
        invalidItems.push({ index: i, reason: validation.reason });
        logs.push(`⚠️ Элемент ${i} невалиден: ${validation.reason}`);
      }
    }

    logs.push(`📊 Итог: ${validItems.length} валидных элементов, ${invalidItems.length} невалидных`);

    if (invalidItems.length > 0) {
      logs.push(`❌ Невалидные элементы: ${JSON.stringify(invalidItems)}`);
    }

    if (validItems.length === 0) {
      logs.push("⚠️ Внимание: нет валидных элементов в ответе");
    }

    const endTime = Date.now();
    logs.push(`✅ Завершение выполнения (время: ${endTime - startTime}мс)`);

    return { items: validItems, logs: logs.join("\n") };
  } catch (e) {
    logs.push(`❌ Критическая ошибка обработки: ${e.message}`);
    logs.push(`📄 Стек ошибки: ${e.stack}`);
    return { items: [], logs: logs.join("\n") };
  }
}

